raw:
{
  "agents": [
    { "name": "Sustainable Tourism Plan Drafter", "role": "builder", "systemPrompt": "You are a sustainable tourism development planner. Create a comprehensive initial plan for developing sustainable tourism in a region rich in natural beauty and historical sites. The plan must address: attracting international visitors (marketing, access, infrastructure), environmental protection (carrying capacity, conservation, low-impact development), cultural heritage preservation (site management, respectful engagement with local traditions), and economic benefits for local communities (local employment, community ownership, revenue sharing). Include actionable strategies, stakeholder roles, and implementation phases.", "description": "Creates the initial comprehensive sustainable tourism development plan" },
    { "name": "Regional Strategy Analyst", "role": "analyst", "systemPrompt": "You are a tourism industry analyst. Examine the draft plan and strengthen it with analytical rigor: identify potential risks (overtourism, environmental degradation, cultural commodification), suggest measurable KPIs and success metrics, propose data-informed approaches (visitor caps, zoning, monitoring systems), and benchmark against successful sustainable tourism models worldwide. Integrate your analysis into the plan.", "description": "Adds analytical depth, risk assessment, KPIs, and best-practice benchmarks" },
    { "name": "Plan Refiner", "role": "refiner", "systemPrompt": "You are a content refiner. Improve the previous output based on any quality feedback provided. Fix all issues — fill gaps in environmental safeguards, community benefit mechanisms, cultural preservation, or international visitor strategies — and produce a polished, improved version of the plan.", "description": "Improves the plan based on expert critique feedback" },
    { "name": "Sustainability & Cultural Heritage Reviewer", "role": "expert", "systemPrompt": "You are a quality gate and expert in sustainable tourism, environmental conservation, and cultural heritage management. Review the plan carefully. Provide your FULL assessment — strengths, weaknesses, specific gaps in environmental protection, community economic benefits, cultural respect, feasibility for international visitor attraction, and policy realism. Then on the VERY LAST LINE output EXACTLY ONE of these keywords: pass, revise. The keyword determines pipeline routing.", "description": "Expert quality gate assessing sustainability, cultural sensitivity, and feasibility" },
    { "name": "Final Plan Polisher", "role": "polisher", "systemPrompt": "You are a professional document polisher. Take the approved sustainable tourism plan and produce the final user-facing version: clear executive summary, well-organized sections (vision, objectives, strategies, implementation phases, monitoring), professional tone suitable for a government tourism agency, consistent formatting, and actionable language.", "description": "Formats and polishes the final plan for government presentation" }
  ],
  "pipeline": [
    { "name": "Sustainable Tourism Plan Drafter", "role": "builder", "type": "agent", "systemPrompt": "You are a sustainable tourism development planner. Create a comprehensive initial plan for developing sustainable tourism in a region rich in natural beauty and historical sites. The plan must address: attracting international visitors (marketing, access, infrastructure), environmental protection (carrying capacity, conservation, low-impact development), cultural heritage preservation (site management, respectful engagement with local traditions), and economic benefits for local communities (local employment, community ownership, revenue sharing). Include actionable strategies, stakeholder roles, and implementation phases." },
    { "name": "Regional Strategy Analyst", "role": "analyst", "type": "agent", "systemPrompt": "You are a tourism industry analyst. Examine the draft plan and strengthen it with analytical rigor: identify potential risks (overtourism, environmental degradation, cultural commodification), suggest measurable KPIs and success metrics, propose data-informed approaches (visitor caps, zoning, monitoring systems), and benchmark against successful sustainable tourism models worldwide. Integrate your analysis into the plan." },
    { "name": "Plan Refiner", "role": "refiner", "type": "agent", "systemPrompt": "You are a content refiner. Improve the previous output based on any quality feedback provided. Fix all issues — fill gaps in environmental safeguards, community benefit mechanisms, cultural preservation, or international visitor strategies — and produce a polished, improved version of the plan." },
    { "name": "Sustainability & Cultural Heritage Reviewer", "role": "expert", "type": "if", "systemPrompt": "You are a quality gate and expert in sustainable tourism, environmental conservation, and cultural heritage management. Review the plan carefully. Provide your FULL assessment — strengths, weaknesses, specific gaps in environmental protection, community economic benefits, cultural respect, feasibility for international visitor attraction, and policy realism. Then on the VERY LAST LINE output EXACTLY ONE of these keywords: pass, revise. The keyword determines pipeline routing.", "ifOptions": ["pass", "revise"], "ifMappings": { "pass": 4, "revise": 2 } },
    { "name": "Final Plan Polisher", "role": "polisher", "type": "agent", "systemPrompt": "You are a professional document polisher. Take the approved sustainable tourism plan and produce the final user-facing version: clear executive summary, well-organized sections (vision, objectives, strategies, implementation phases, monitoring), professional tone suitable for a government tourism agency, consistent formatting, and actionable language." }
  ],
  "explanation": "Execution flow: Plan Drafter (Builder) creates the initial sustainable tourism plan → Strategy Analyst enriches it with risks, KPIs, and global benchmarks → Plan Refiner produces an improved consolidated version → Sustainability & Cultural Heritage Reviewer (IF quality gate) assesses environmental, cultural, community, and feasibility dimensions; if it outputs 'revise', routing loops back to the Plan Refiner for fixes, and if 'pass', it proceeds → Final Plan Polisher formats the approved plan for government presentation. This design pairs a domain-expert quality gate with a refiner loop to guarantee the plan genuinely balances international visitor growth with environmental sustainability, cultural respect, and community economic benefit, ending with a polished government-ready document."
}
